R,C=26,29
pts=[(0,2),(4,3),(4,5),(5,16),(6,18),(7,15),(8,5),(9,16),(10,25),(11,0),(11,16),(12,6),(13,12),(14,20),(14,24),(16,6),(17,14),(17,17),(18,13),(19,14),(19,27),(20,21),(22,22),(22,28),(25,8)]
g=[[2]*C for _ in range(R)]
for r,c in pts:g[r][c]=6
# Fill cells between pairs of markers sharing a row or column
from collections import defaultdict
rows=defaultdict(list); cols=defaultdict(list)
for r,c in pts: rows[r].append(c); cols[c].append(r)
for r,cs in rows.items():
    if len(cs)>1:
        for c in range(min(cs),max(cs)+1):
            if g[r][c]!=6:g[r][c]=3
for c,rs in cols.items():
    if len(rs)>1:
        for r in range(min(rs),max(rs)+1):
            if g[r][c]!=6:g[r][c]=3
import json
print(json.dumps({'action':'submit','grid':g}))
